#!/usr/bin/env node
// Generates the per-endpoint code of every SDK from openapi/openapi.json.
//   node scripts/generate.mjs           write the files
//   node scripts/generate.mjs --check   exit 1 if any generated file is stale (CI)
// The hand-written cores (HTTP, errors, rate-limit headers) live next to the
// generated files and never change when an endpoint is added.
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const spec = JSON.parse(readFileSync(join(root, 'openapi/openapi.json'), 'utf8'));
const check = process.argv.includes('--check');
const HEADER = 'Generated by scripts/generate.mjs from openapi/openapi.json - do not edit.';

// ---------------------------------------------------------------- model
const groups = spec.tags.map(t => ({ key: t.name, description: t.description }));
const endpoints = Object.entries(spec.paths).map(([path, item]) => {
  const op = item.get;
  const [, group, name] = path.split('/');
  return {
    path, group, name,
    summary: op.summary,
    description: op.description,
    params: (op.parameters || []).map(p => ({
      name: p.name, required: !!p.required, description: p.description,
      type: p.schema && p.schema.type === 'integer' ? 'int' : 'string', example: p.example,
    })),
  };
});

const words = s => s.replace(/([a-z])([A-Z])/g, '$1 $2').split(/[^A-Za-z0-9]+/).filter(Boolean);
const camel = s => words(s).map((w, i) => i ? w[0].toUpperCase() + w.slice(1).toLowerCase() : w.toLowerCase()).join('');
const pascal = s => words(s).map(w => w[0].toUpperCase() + w.slice(1).toLowerCase()).join('');
const snake = s => words(s).map(w => w.toLowerCase()).join('_');
const ordered = e => [...e.params.filter(p => p.required), ...e.params.filter(p => !p.required)];
const oneLine = s => (s || '').replace(/\s+/g, ' ').trim();

const out = {};

// ---------------------------------------------------------------- JavaScript
{
  const table = JSON.stringify(endpoints.map(e => ({ group: e.group, name: e.name, method: camel(e.name), params: e.params.map(p => [p.name, p.required ? 1 : 0]) })), null, 2);
  out['packages/js/src/endpoints.cjs'] = `// ${HEADER}\nexports.ENDPOINTS = ${table};\n`;

  let dts = `// ${HEADER}\nimport type { A2zClientOptions, A2zResult, RateLimit } from './types.js';\n\n`;
  for (const g of groups) {
    dts += `/** ${oneLine(g.description)} */\nexport interface ${pascal(g.key)}Group {\n`;
    for (const e of endpoints.filter(x => x.group === g.key)) {
      const fields = e.params.map(p => `    /** ${oneLine(p.description)}${p.example ? ` e.g. \`${p.example}\`` : ''} */\n    ${p.name}${p.required ? '' : '?'}: ${p.type === 'int' ? 'number' : 'string'};`).join('\n');
      dts += `  /** ${oneLine(e.summary)}. ${oneLine(e.description)} */\n  ${camel(e.name)}(params: {\n${fields}\n  }, options?: { signal?: AbortSignal }): Promise<A2zResult>;\n`;
    }
    dts += `}\n\n`;
  }
  dts += `export declare class A2zClient {\n  constructor(options?: A2zClientOptions);\n`;
  for (const g of groups) dts += `  readonly ${camel(g.key)}: ${pascal(g.key)}Group;\n`;
  dts += `  /** Calls any endpoint by group and name, e.g. call('ssl', 'certificate', { host }). */\n  call(group: string, name: string, params?: Record<string, string | number | undefined>, options?: { signal?: AbortSignal }): Promise<A2zResult>;\n`;
  dts += `  /** Limits from the most recent response. */\n  readonly lastRateLimit: RateLimit | null;\n}\n`;
  out['packages/js/src/client.d.ts'] = dts;
}

// ---------------------------------------------------------------- Python
{
  let py = `# ${HEADER}\nfrom __future__ import annotations\n\nfrom typing import Any, Dict, Optional, TYPE_CHECKING\n\nif TYPE_CHECKING:  # pragma: no cover\n    from .client import A2zClient\n\n`;
  for (const g of groups) {
    py += `\nclass ${pascal(g.key)}Group:\n    """${oneLine(g.description)}"""\n\n    def __init__(self, client: "A2zClient") -> None:\n        self._client = client\n`;
    for (const e of endpoints.filter(x => x.group === g.key)) {
      const args = ordered(e).map(p => `${snake(p.name)}: ${p.required ? '' : 'Optional['}${p.type === 'int' ? 'int' : 'str'}${p.required ? '' : '] = None'}`).join(', ');
      const dict = e.params.map(p => `"${p.name}": ${snake(p.name)}`).join(', ');
      py += `\n    def ${snake(e.name)}(self, ${args}) -> Dict[str, Any]:\n        """${oneLine(e.summary)}. ${oneLine(e.description).replace(/"/g, "'")}"""\n        return self._client.call("${e.group}", "${e.name}", {${dict}})\n`;
    }
  }
  py += `\n\nGROUPS = {${groups.map(g => `"${snake(g.key)}": ${pascal(g.key)}Group`).join(', ')}}\n`;
  out['packages/python/src/a2ztools/_endpoints.py'] = py;
}

// ---------------------------------------------------------------- .NET
{
  const csType = p => p.type === 'int' ? (p.required ? 'int' : 'int?') : (p.required ? 'string' : 'string?');
  const xml = s => oneLine(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  let cs = `// <auto-generated>${HEADER}</auto-generated>\n#nullable enable\nusing System.Collections.Generic;\nusing System.Threading;\nusing System.Threading.Tasks;\n\nnamespace A2zTools.Api\n{\n`;
  cs += `    public partial class A2zClient\n    {\n`;
  for (const g of groups) cs += `        /// <summary>${xml(g.description)}</summary>\n        public ${pascal(g.key)}Group ${pascal(g.key)} => new ${pascal(g.key)}Group(this);\n`;
  cs += `    }\n`;
  for (const g of groups) {
    cs += `\n    /// <summary>${xml(g.description)}</summary>\n    public sealed class ${pascal(g.key)}Group\n    {\n        private readonly A2zClient _client;\n        internal ${pascal(g.key)}Group(A2zClient client) { _client = client; }\n`;
    for (const e of endpoints.filter(x => x.group === g.key)) {
      const ps = ordered(e);
      const args = ps.map(p => `${csType(p)} ${camel(p.name)}${p.required ? '' : ' = null'}`).concat(['CancellationToken cancellationToken = default']).join(', ');
      const dict = e.params.map(p => `["${p.name}"] = ${p.type === 'int' ? `${camel(p.name)}?.ToString()` : camel(p.name)}`).join(', ');
      cs += `\n        /// <summary>${xml(e.summary)}. ${xml(e.description)}</summary>\n`;
      for (const p of ps) cs += `        /// <param name="${camel(p.name)}">${xml(p.description)}</param>\n`;
      cs += `        /// <param name="cancellationToken">Cancels the request.</param>\n`;
      cs += `        public Task<A2zResponse> ${pascal(e.name)}Async(${args})\n            => _client.CallAsync("${e.group}", "${e.name}", new Dictionary<string, string?> { ${dict} }, cancellationToken);\n`;
    }
    cs += `    }\n`;
  }
  cs += `}\n`;
  out['packages/dotnet/src/A2zTools.Api/A2zClient.Endpoints.g.cs'] = cs;
}

// ---------------------------------------------------------------- PHP
{
  let php = `<?php\n// ${HEADER}\ndeclare(strict_types=1);\n\nnamespace A2zTools\\Api;\n\n`;
  for (const g of groups) {
    php += `/** ${oneLine(g.description)} */\nfinal class ${pascal(g.key)}Group\n{\n    public function __construct(private Client $client)\n    {\n    }\n`;
    for (const e of endpoints.filter(x => x.group === g.key)) {
      const ps = ordered(e);
      const args = ps.map(p => `${p.required ? '' : '?'}${p.type === 'int' ? 'int' : 'string'} $${camel(p.name)}${p.required ? '' : ' = null'}`).join(', ');
      const arr = e.params.map(p => `'${p.name}' => $${camel(p.name)}`).join(', ');
      php += `\n    /**\n     * ${oneLine(e.summary)}. ${oneLine(e.description)}\n     *\n     * @return array<string, mixed>\n     */\n    public function ${camel(e.name)}(${args}): array\n    {\n        return $this->client->call('${e.group}', '${e.name}', [${arr}]);\n    }\n`;
    }
    php += `}\n\n`;
  }
  out['packages/php/src/Endpoints.php'] = php.trimEnd() + '\n';
}

// ---------------------------------------------------------------- write / check
let stale = 0;
for (const [rel, text] of Object.entries(out)) {
  const file = join(root, rel);
  const current = existsSync(file) ? readFileSync(file, 'utf8').replace(/\r\n/g, '\n') : null;
  if (current === text) continue;
  if (check) { console.error('stale: ' + rel); stale++; continue; }
  writeFileSync(file, text);
  console.log('wrote ' + rel);
}
if (check && stale) { console.error(stale + ' generated file(s) are out of date: run node scripts/generate.mjs'); process.exit(1); }
console.log(`${endpoints.length} endpoints, ${groups.length} groups`);
